-- V20.9.27.47 — category-driven product schema
ALTER TABLE commerce_categories ADD COLUMN fields_schema_json TEXT NOT NULL DEFAULT '[]';
UPDATE template_catalog SET description='Website bán hàng tổng quát với trang chi tiết sản phẩm, checkout popup lớn, thuộc tính/biến thể động theo từng danh mục và quản trị tự sinh trường.',updated_at=CURRENT_TIMESTAMP WHERE template_key='dich-vu-5';

UPDATE commerce_categories SET fields_schema_json='[{"key":"cpu","label":"CPU","type":"text","required":false,"filterable":true,"show_in_specs":true},{"key":"ram","label":"RAM","type":"select","options":["8GB","16GB","32GB","64GB"],"filterable":true,"variant":true,"show_in_specs":true},{"key":"storage","label":"Lưu trữ","type":"select","options":["256GB","512GB","1TB"],"filterable":true,"variant":true,"show_in_specs":true}]' WHERE name='Công nghệ' AND (fields_schema_json='[]' OR fields_schema_json='');
UPDATE commerce_categories SET fields_schema_json='[{"key":"size","label":"Kích thước","type":"size","options":["S","M","L","XL"],"required":true,"filterable":true,"variant":true,"show_in_specs":true},{"key":"color","label":"Màu sắc","type":"color","options":["Đen","Trắng","Kem","Nâu"],"filterable":true,"variant":true,"show_in_specs":true},{"key":"material","label":"Chất liệu","type":"text","filterable":true,"show_in_specs":true}]' WHERE name='Thời trang' AND (fields_schema_json='[]' OR fields_schema_json='');
UPDATE commerce_categories SET fields_schema_json='[{"key":"capacity","label":"Dung tích","type":"select","options":["15ml","30ml","50ml","100ml"],"filterable":true,"variant":true,"show_in_specs":true},{"key":"skin_type","label":"Loại da","type":"multiselect","options":["Da dầu","Da khô","Da nhạy cảm","Mọi loại da"],"filterable":true,"show_in_specs":true},{"key":"origin","label":"Xuất xứ","type":"text","show_in_specs":true}]' WHERE name='Mỹ phẩm' AND (fields_schema_json='[]' OR fields_schema_json='');
